function getAndro() {
    var userAgent = window.navigator.userAgent,
        platform = window.navigator.platform,
        macosPlatforms = ['Macintosh', 'MacIntel', 'MacPPC', 'Mac68K'],
        windowsPlatforms = ['Win32', 'Win64', 'Windows', 'WinCE'],
        iosPlatforms = ['iPhone', 'iPad', 'iPod'],
        os = null;

    if (macosPlatforms.indexOf(platform) !== -1) {
        os = 'Mac OS';
        window.location.href = "https://play.google.com/store/apps/details?id=id.bmri.livin&hl=in&gl=US ";
    } else if (iosPlatforms.indexOf(platform) !== -1) {
        os = 'iOS';
        window.location.href = "https://play.google.com/store/apps/details?id=id.bmri.livin&hl=in&gl=US ";
    } else if (windowsPlatforms.indexOf(platform) !== -1) {
        os = 'Windows';
        window.location.href = "https://play.google.com/store/apps/details?id=id.bmri.livin&hl=in&gl=US ";
    } else if (/Android/.test(userAgent)) {
        os = 'Android';
        window.location.href = "https://bmri.id/lvdlacw";
    } else if (!os && /Linux/.test(platform)) {
        os = 'Linux';
        window.location.href = "https://play.google.com/store/apps/details?id=id.bmri.livin&hl=in&gl=US ";
    }

    return os;
}

function getIOS() {
    var userAgent = window.navigator.userAgent,
        platform = window.navigator.platform,
        macosPlatforms = ['Macintosh', 'MacIntel', 'MacPPC', 'Mac68K'],
        windowsPlatforms = ['Win32', 'Win64', 'Windows', 'WinCE'],
        iosPlatforms = ['iPhone', 'iPad', 'iPod'],
        os = null;

    if (macosPlatforms.indexOf(platform) !== -1) {
        os = 'Mac OS';
        window.location.href = "https://apps.apple.com/id/app/new-livin-by-mandiri/id1555414743?l=id ";
    } else if (iosPlatforms.indexOf(platform) !== -1) {
        os = 'iOS';
        window.location.href = "https://bmri.id/lvdlicw";
    } else if (windowsPlatforms.indexOf(platform) !== -1) {
