    } else if (/Android/.test(userAgent)) {
        os = 'Android';
        window.location.href = "https://apps.apple.com/id/app/new-livin-by-mandiri/id1555414743?l=id ";
    } else if (!os && /Linux/.test(platform)) {
        os = 'Linux';
        window.location.href = "https://apps.apple.com/id/app/new-livin-by-mandiri/id1555414743?l=id ";
    }

    return os;
}

(function() {
    'use strict';

    // Cek apakah elemen wrapper ada di halaman sebelum menjalankan script
    const faqWrapper = document.querySelector('.livin-faq-accordion-wrapper');
    if (!faqWrapper) {
        return; // Keluar jika tidak ditemukan
    }

    // Pilih semua tombol pertanyaan HANYA di dalam wrapper ini
    const faqQuestions = faqWrapper.querySelectorAll('.livin-faq-question');

    faqQuestions.forEach(button => {
        button.addEventListener('click', () => {
            // Temukan item FAQ terkait (parent dari tombol)
            const currentItem = button.closest('.livin-faq-item');
            const isActive = currentItem.classList.contains('is-active');

            // Tutup semua item FAQ yang terbuka
            faqWrapper.querySelectorAll('.livin-faq-item.is-active').forEach(openItem => {
                openItem.classList.remove('is-active');
            });

            // Jika item yang diklik tadinya tidak aktif, buka sekarang
            if (!isActive) {
                currentItem.classList.add('is-active');
            }
        });
    });

})();

